"use client";
/* Generated by Antigravity AI - Adhering to SOLID & Design Patterns */

import { useState, useEffect, useRef } from "react";
import { useNavigate } from "react-router-dom";
import { Save, ArrowLeft } from "lucide-react";
import { apiClient } from "@/services/api.service";
import { ArticleEditorBasicComponent } from "../components/ArticleEditorBasicComponent";
import { ArticleEditorSeoComponent } from "../components/ArticleEditorSeoComponent";
import { ArticleEditorSettingsComponent } from "../components/ArticleEditorSettingsComponent";
import { ArticleEditorAiAssistantComponent } from "../components/ArticleEditorAiAssistantComponent";
import { IArticleFormData } from "../admin-articles.types";

import { toast } from "sonner";

interface Props {
  initialData?: IArticleFormData & { _id?: string };
  isEdit?: boolean;
}

export default function ArticleEditorModal({
  initialData,
  isEdit = false,
}: Props) {
  const navigate = useNavigate();
  const [categories, setCategories] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [formData, setFormData] = useState<IArticleFormData>({
    title: initialData?.title || "",
    slug: initialData?.slug || "",
    categoryId: initialData?.categoryId || "NONE",
    description: initialData?.description || "",
    content: initialData?.content || "",
    thumbnail: initialData?.thumbnail || "",
    isPublished: initialData?.isPublished ?? true,
    isPinned: initialData?.isPinned ?? false,
    seoMeta: {
      title: initialData?.seoMeta?.title || "",
      description: initialData?.seoMeta?.description || "",
      keywords: initialData?.seoMeta?.keywords || "",
    },
  });

  // Trạng thái cho AI
  const [showAiModal, setShowAiModal] = useState(false);
  const [aiProvider, setAiProvider] = useState<"gemini" | "openai" | "openrouter">("openrouter");
  const [aiApiKey, setAiApiKey] = useState("");
  const [aiTopic, setAiTopic] = useState("");
  const [aiOutline, setAiOutline] = useState("");
  const [aiModel, setAiModel] = useState("");
  const [isAiLoading, setIsAiLoading] = useState(false);
  const [isAiGeneratingContent, setIsAiGeneratingContent] = useState(false);

  // Trạng thái Editor & Auto-save
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [lastSaved, setLastSaved] = useState<Date | null>(null);
  const [draftId, setDraftId] = useState<string | null>(
    initialData?._id || null,
  );
  const startTimeRef = useRef<number>(Date.now());

  useEffect(() => {
    // Lấy danh sách category từ CMS (module đa cấp) để map vào categoryId (nếu cần)
    apiClient
      .get("/categories/tree")
      .then((res: any) => {
        const data = Array.isArray(res) ? res : res.data || [];
        setCategories(data);
      })
      .catch(console.error);
  }, []);

  // Auto-save sau 5 phút (300,000 ms), lưu nháp mỗi 30s
  useEffect(() => {
    const interval = setInterval(() => {
      const timeElapsed = Date.now() - startTimeRef.current;
      if (timeElapsed >= 5 * 60 * 1000) {
        handleAutoSave();
      }
    }, 30000); // Check every 30s

    return () => clearInterval(interval);
  }, [formData, draftId, isEdit]); // Cần track formData hiện tại

  const handleAutoSave = async () => {
    // Không lưu nếu thiếu field bắt buộc
    if (!formData.title || !formData.slug || !formData.categoryId) return;

    try {
      const payload = {
        ...formData,
        categoryId: formData.categoryId ? formData.categoryId : undefined,
        isPublished: false, // Auto-save luôn là bản nháp để an toàn
      };

      if (draftId || isEdit) {
        const idToUpdate = draftId || initialData?._id;
        if (idToUpdate) {
          await apiClient.put(`/articles/${idToUpdate}`, payload);
          setLastSaved(new Date());
        }
      } else {
        const res = await apiClient.post("/articles", payload);
        const newArticleId = Array.isArray(res) ? undefined : (res as any)._id;
        if (newArticleId) {
          setDraftId(newArticleId);
          setLastSaved(new Date());
          window.history.replaceState(
            null,
            "",
            `/admin/articles/${newArticleId}`,
          );
        }
      }
    } catch (error) {
      console.error("Auto-save failed", error);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);

    // Validate
    if (!formData.title || !formData.slug || !formData.content) {
      toast.error("Vui lòng nhập đầy đủ Tiêu đề, Slug và Nội dung!");
      setLoading(false);
      return;
    }

    try {
      const payload = {
        ...formData,
        categoryId: formData.categoryId ? formData.categoryId : undefined,
      };

      if (isEdit || draftId) {
        const idToUpdate = draftId || initialData?._id;
        await apiClient.put(`/articles/${idToUpdate}`, payload);
        toast.success("Cập nhật bài viết thành công!");
      } else {
        await apiClient.post("/articles", payload);
        toast.success("Tạo bài viết thành công!");
      }
      navigate("/articles");
    } catch (err: unknown) {
      console.error(err);
      toast.error(err instanceof Error ? err.message : "Có lỗi xảy ra khi lưu bài viết");
    } finally {
      setLoading(false);
    }
  };

  const handleGenerateOutline = async () => {
    if (!aiTopic) {
      toast.error("Vui lòng nhập chủ đề để AI xử lý");
      return;
    }
    setIsAiLoading(true);
    try {
      const res = await apiClient.post<Record<string, unknown>>("/ai/outline", {
        topic: aiTopic,
        keywords: formData.seoMeta.keywords
          ? formData.seoMeta.keywords.split(",").map((k) => k.trim())
          : [],
        provider: aiProvider,
        apiKey: aiApiKey || undefined,
        model: aiModel || undefined,
      });

      const resData = res as Record<string, unknown>;
      const newOutline = (resData.outline || (resData.data as Record<string, unknown>)?.outline) as string;
      if (newOutline) {
        setAiOutline(newOutline);
      }
    } catch (err: unknown) {
      toast.error("Lỗi khi gọi AI: " + (err instanceof Error ? err.message : "Không thể kết nối API AI"));
    } finally {
      setIsAiLoading(false);
    }
  };

  const handleGenerateContent = async () => {
    if (!aiOutline) return;
    setIsAiGeneratingContent(true);
    try {
      const res = await apiClient.post<any>("/api/ai/generate-content", {
        topic: aiTopic,
        keywords: formData.seoMeta.keywords
          ? formData.seoMeta.keywords.split(",").map((k) => k.trim())
          : [],
        outline: aiOutline,
        provider: aiProvider,
        apiKey: aiApiKey || undefined,
        model: aiModel || undefined,
      });

      const newContent = res.content || res.data?.content;
      if (newContent) {
        setFormData((prev) => ({
          ...prev,
          content: prev.content
            ? prev.content + "<br/>" + newContent
            : newContent,
        }));
        setShowAiModal(false);
        setAiOutline("");
      }
    } catch (error: any) {
      toast.error("Lỗi khi gọi AI sinh nội dung: " + (error.message || "Không thể kết nối API AI"));
    } finally {
      setIsAiGeneratingContent(false);
    }
  };

  return (
    <form
      onSubmit={handleSubmit}
      className="space-y-6 max-w-10xl mx-auto pb-12"
    >
      <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 bg-white dark:bg-slate-900/80 backdrop-blur-md p-4 sm:p-5 rounded-2xl shadow-xs border border-gray-100 dark:border-slate-800">
        <button
          type="button"
          onClick={() => navigate(-1)}
          className="flex items-center gap-2 p-2 rounded-xl border border-gray-200 dark:border-slate-700 text-gray-600 dark:text-gray-300 hover:text-gray-900 dark:hover:text-white transition-colors cursor-pointer w-fit"
        >
          <ArrowLeft size={18} />
          <span className="text-sm font-semibold">Quay lại</span>
        </button>
        <div className="flex items-center justify-between sm:justify-end gap-4">
          {lastSaved && (
            <span className="text-xs text-gray-400">
              Đã lưu tự động lúc: {lastSaved.toLocaleTimeString()}
            </span>
          )}
          <button
            type="submit"
            disabled={loading}
            className="bg-blue-600 hover:bg-blue-700 text-white px-6 py-2.5 rounded-xl font-semibold flex items-center justify-center gap-2 transition-colors disabled:opacity-50 cursor-pointer shadow-md shadow-blue-500/20"
          >
            <Save size={18} />
            <span>
              {loading ? "Đang lưu..." : isEdit ? "Cập Nhật" : "Xuất Bản"}
            </span>
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Cột chính: Nội dung & SEO */}
        <div className="lg:col-span-2 space-y-6">
          <ArticleEditorBasicComponent
            formData={formData}
            setFormData={setFormData}
            isEdit={isEdit}
            isFullscreen={isFullscreen}
            setIsFullscreen={setIsFullscreen}
            setShowAiModal={setShowAiModal}
          />
          <ArticleEditorSeoComponent formData={formData} setFormData={setFormData} />
        </div>

        {/* Cột phải: Settings */}
        <ArticleEditorSettingsComponent
          formData={formData}
          setFormData={setFormData}
          categories={categories}
        />
      </div>

      {/* Modal Trợ lý AI */}
      {showAiModal && (
        <ArticleEditorAiAssistantComponent
          aiProvider={aiProvider}
          setAiProvider={setAiProvider}
          aiApiKey={aiApiKey}
          setAiApiKey={setAiApiKey}
          aiModel={aiModel}
          setAiModel={setAiModel}
          aiTopic={aiTopic}
          setAiTopic={setAiTopic}
          aiOutline={aiOutline}
          setAiOutline={setAiOutline}
          isAiLoading={isAiLoading}
          isAiGeneratingContent={isAiGeneratingContent}
          handleGenerateOutline={handleGenerateOutline}
          handleGenerateContent={handleGenerateContent}
          setShowAiModal={setShowAiModal}
          keywords={formData.seoMeta.keywords}
        />
      )}
    </form>
  );
}
